control.onControlLoad:
for (const name of ["websiteInformation2"]) {
    const heading = ee.getControl(name);
    heading.setAttribute("role", "heading");
    heading.setAttribute("aria-level", "1");
}
for (const name of ["websiteUse", "privacy2"]) {
    const heading = ee.getControl(name);
    heading.setAttribute("role", "heading");
    heading.setAttribute("aria-level", "2");
}
const anchors = {"use":"use","privacy":"privacy"};
function showSection() {
    const section = anchors[location.hash.slice(1)];
    if (section) ee.getControl(section)?.scrollIntoView({block: "start"});
}
window.addEventListener("hashchange", showSection);
requestAnimationFrame(showSection);

control.onCreate:
const cell = sender.label.rows[0].cells[0];
const link = document.createElement("a");
link.href = "mailto:support@epage.dev";

link.textContent = cell.textContent;
cell.replaceChildren(link);
